<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sell Point Requests</title></head><body><div style="max-width:1100px;margin:auto;padding:25px"><h2>Sell Point Request List</h2><form><input type="date" name="start"> <input type="date" name="end"> <select name="status"><option value="">All</option><option>Pending</option><option>Paid</option><option>Cancel</option></select> <button>Filter</button></form><table border="1" cellpadding="8" cellspacing="0" width="100%" style="margin-top:15px"><thead><tr><th>Point</th><th>Requested</th><th>Buyer</th><th>Status</th><th>Screenshot</th><th>Approve</th><th>Cancel</th><th>Action</th></tr></thead><tbody id="rows"></tbody></table></div><script>async function load(){let p=new URLSearchParams(location.search);let r=await fetch('{{ route('student.sellpoint.list') }}?length=100&filter_start_date='+(p.get('start')||'')+'&filter_end_date='+(p.get('end')||'')+'&filter_approve_status='+(p.get('status')||''));let j=await r.json();document.getElementById('rows').innerHTML=j.data.map(x=>'<tr><td>'+x.point+'</td><td>'+x.requested_at+'</td><td>'+x.username+'</td><td>'+x.raw_status+'</td><td>'+x.screenshot+'</td><td>'+x.approve_at+'</td><td>'+x.cancelled_at+'</td><td>'+(x.raw_status==='Pending'?'<button onclick="act(\'complain\','+x.id+')">Complain</button>':'')+(x.raw_status==='Paid'&&x.is_transfer==1?' <button onclick="act(\'accept\','+x.id+')">Confirm Payment</button>':'')+'</td></tr>').join('')}function act(a,id){fetch('/student/sellpointlist/'+a,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({id})}).then(r=>r.json()).then(x=>{alert(x.success||x.error);load()})}load()</script></body></html>